package sidecar
import("archive/zip";"bytes";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"io";"path";"strings")
type MLFInfo struct{Profile string `json:"profile"`;Version string `json:"mlf_version"`;DocumentID string `json:"document_id"`;Title string `json:"title,omitempty"`;CompilerName string `json:"compiler_name"`;CompilerVersion string `json:"compiler_version"`;Conformance []string `json:"conformance"`;FingerprintAlgorithm string `json:"fingerprint_algorithm"`;Fingerprints map[string]string `json:"fingerprints"`;NativeSHA256 string `json:"native_sha256"`;NativeBytes int `json:"native_bytes"`;EntryCount int `json:"package_entry_count"`}
type mlfManifest struct{Version string `json:"mlf_version"`;DocumentID string `json:"document_id"`;Title string `json:"title"`;Conformance []string `json:"conformance"`;Fingerprints string `json:"fingerprints"`;Compiler struct{Name string `json:"name"`;Version string `json:"version"`} `json:"compiler"`};type fpFile struct{Algorithm string `json:"algorithm"`;Structural string `json:"structural_hash"`;Content string `json:"content_hash"`;Semantic string `json:"semantic_hash"`;Presentation string `json:"presentation_hash"`};type checksumFile struct{Algorithm string `json:"algorithm"`;Files []struct{Path string `json:"path"`;SHA256 string `json:"sha256"`;Bytes *int `json:"bytes"`} `json:"files"`}
func safeZipName(name string)bool{if name==""||strings.Contains(name,"\\")||strings.HasPrefix(name,"/"){return false};cleaned:=path.Clean(name);if cleaned=="."||cleaned==".."||strings.HasPrefix(cleaned,"../"){return false};return cleaned==name||cleaned+"/"==name};func readZipFile(f *zip.File)([]byte,error){r,e:=f.Open();if e!=nil{return nil,e};defer r.Close();return io.ReadAll(r)};func prefixedSHA(data []byte)string{h:=sha256.Sum256(data);return "sha256:"+hex.EncodeToString(h[:])};func validPrefixedSHA(s string)bool{if !strings.HasPrefix(s,"sha256:")||len(s)!=71{return false};_,e:=hex.DecodeString(strings.TrimPrefix(s,"sha256:"));return e==nil}
func InspectMLF(raw []byte)(MLFInfo,error){zr,err:=zip.NewReader(bytes.NewReader(raw),int64(len(raw)));if err!=nil{return MLFInfo{},fmt.Errorf("PROFILE_MLF_INVALID_ZIP:%w",err)};files:=map[string]*zip.File{};for _,f:=range zr.File{if !safeZipName(f.Name){return MLFInfo{},fmt.Errorf("P5_MLF_UNSAFE_PATH:%s",f.Name)};if _,ok:=files[f.Name];ok{return MLFInfo{},fmt.Errorf("P5_MLF_DUPLICATE_ENTRY:%s",f.Name)};if f.Mode()&0o170000==0o120000{return MLFInfo{},fmt.Errorf("P5_MLF_SYMLINK_FORBIDDEN:%s",f.Name)};files[f.Name]=f};mf,ok:=files["manifest.json"];if !ok{return MLFInfo{},fmt.Errorf("PROFILE_MLF_MANIFEST_MISSING")};mb,err:=readZipFile(mf);if err!=nil{return MLFInfo{},err};var m mlfManifest;if err:=json.Unmarshal(mb,&m);err!=nil{return MLFInfo{},fmt.Errorf("PROFILE_MLF_MANIFEST_INVALID:%w",err)};if m.Version!="1.0"{return MLFInfo{},fmt.Errorf("PROFILE_NATIVE_VERSION_UNSUPPORTED")};if m.DocumentID==""||m.Compiler.Name==""||m.Compiler.Version==""||len(m.Conformance)==0{return MLFInfo{},fmt.Errorf("P5_MLF_MANIFEST_INVALID")};fpPath:=m.Fingerprints;if fpPath==""{fpPath="reports/fingerprints.json"};ff,ok:=files[fpPath];if !ok{return MLFInfo{},fmt.Errorf("P5_MLF_FINGERPRINT_FILE_MISSING")};fb,err:=readZipFile(ff);if err!=nil{return MLFInfo{},err};var fp fpFile;if err:=json.Unmarshal(fb,&fp);err!=nil{return MLFInfo{},fmt.Errorf("P5_MLF_FINGERPRINT_INVALID:%w",err)};vals:=map[string]string{"structural":fp.Structural,"content":fp.Content,"semantic":fp.Semantic,"presentation":fp.Presentation};if fp.Algorithm==""{return MLFInfo{},fmt.Errorf("P5_MLF_FINGERPRINT_INVALID")};for _,v:=range vals{if !validPrefixedSHA(v){return MLFInfo{},fmt.Errorf("P5_MLF_FINGERPRINT_INVALID")}};cf,ok:=files["checksums.json"];if !ok{return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_FILE_MISSING")};cb,err:=readZipFile(cf);if err!=nil{return MLFInfo{},err};var checks checksumFile;if err:=json.Unmarshal(cb,&checks);err!=nil{return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_INVALID:%w",err)};if checks.Algorithm!="sha256"{return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_INVALID")};seen:=map[string]bool{};for _,row:=range checks.Files{if !safeZipName(row.Path)||seen[row.Path]{return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_INVALID:%s",row.Path)};seen[row.Path]=true;zf,ok:=files[row.Path];if !ok{return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_INVALID:%s",row.Path)};payload,err:=readZipFile(zf);if err!=nil{return MLFInfo{},err};if row.SHA256!=prefixedSHA(payload){return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_MISMATCH:%s",row.Path)};if row.Bytes!=nil&&*row.Bytes!=len(payload){return MLFInfo{},fmt.Errorf("P5_MLF_CHECKSUM_MISMATCH:%s",row.Path)}};h:=sha256.Sum256(raw);return MLFInfo{Profile:"mlf-1.0",Version:"1.0",DocumentID:m.DocumentID,Title:m.Title,CompilerName:m.Compiler.Name,CompilerVersion:m.Compiler.Version,Conformance:m.Conformance,FingerprintAlgorithm:fp.Algorithm,Fingerprints:vals,NativeSHA256:hex.EncodeToString(h[:]),NativeBytes:len(raw),EntryCount:len(zr.File)},nil}
